'use strict'

/**
 * nexus/controller — the trusted host Nexus Controller service (P1, C01/C04).
 *
 * One host Cordis row (`nexus-controller-host`, generated by
 * scripts/Build-NexusHomePatch.cjs) applies this plugin and provides the
 * `nexusController` service. The per-plane `aih-controller` rows
 * (AihController.cjs, mounted once per preset closure) are thin compatibility
 * bridges: they keep the existing DSH hook wiring, binding cache and turn
 * semantics, and resolve this service at every authority point.
 *
 * The host Controller owns or coordinates:
 *   - strategy dispatch through the strategy index (EMv2 Muse, EMv1 Dual
 *     compatibility; Nova later) with contract/version validation;
 *   - the single legacy PowerShell runner (Task/Route/NexusWorkspace/
 *     Engineering/Verify-Project/Review ...) and its accounting;
 *   - authorized task/attempt transitions, serialized per task generation
 *     across every bridge mount and every asynchronous observer;
 *   - deduplication of DSH session events, so a terminal `turn/end` produces
 *     its failure/interrupt/reroute side effects once even when several
 *     standing preset mounts observe the same session;
 *   - runtime readiness (strategies, runner, attached plane bridges) and
 *     service lifecycle (closing admission on disposal).
 *
 * It deliberately does NOT own a task store: TaskController.ps1 stays the
 * ledger writer, Route.ps1/Routing.ps1 the route-state writer, the existing
 * session-bindings document keeps its schema, and the Nexus Model Registry
 * stays the only model/entitlement authority. Strategies cannot write state
 * and have no completion decision.
 *
 * Cordis plugins are trusted host code; this service is an authority
 * boundary inside one process, not a security sandbox.
 */

const path = require('node:path')
const legacyCliModule = require('./legacy-cli.cjs')
const strategyIndexModule = require('./strategy-index.cjs')
const museStrategy = require('./strategies/muse.cjs')
const legacyDualStrategy = require('./strategies/legacy-dual.cjs')
const bindingStoreModule = require('./binding-store.cjs')
const hostOwnershipModule = require('./host-ownership.cjs')
const taskApiModule = require('./task-api.cjs')
const ipcModule = require('./ipc.cjs')
const intakeStoreModule = require('./intake-store.cjs')
const brokerModule = require('./broker.cjs')
const managedTasksModule = require('./managed-tasks.cjs')
const gatewayPolicyModule = require('./gateway-policy.cjs')

const CONTROLLER_SERVICE = 'nexusController'
const CONTROLLER_CONTRACT_MAJOR = 1
const CONTROLLER_BUILD = 'nexus-controller-p2b2b-1'
// Gateway builds whose `gateway/authorize` hook Nexus has verified (sha256 of
// @deepseek-ai/dsh-api-gateway/lib/index.js). A digest match is necessary but
// not sufficient: the startup self-test must also observe a refusal.
const GATEWAY_HOOK_DIGESTS = Object.freeze({
  '12e5577b6ae0c19d2d826790f409e086513a41a33014fc45ae57d257a57a14c8': 'dsh-v0.2.2-rc.1+nexus-gateway-authorize-1',
})
// Platforms whose managed admission has native real-host evidence.
const QUALIFIED_PLATFORMS = Object.freeze(['darwin'])
const BUILTIN_STRATEGIES = Object.freeze([museStrategy, legacyDualStrategy])
const MANDATORY_STRATEGY_IDS = Object.freeze([museStrategy.MUSE_STRATEGY_ID, legacyDualStrategy.LEGACY_DUAL_STRATEGY_ID])
const EVENT_DEDUP_WINDOW = 512

class ControllerError extends Error {
  constructor(code, message) {
    super(`${code}: ${message}`)
    this.code = code
  }
}

function resolveInstallRoot(env) {
  const environment = env || process.env
  if (environment.AIH_INSTALL_ROOT && String(environment.AIH_INSTALL_ROOT).trim() !== '') return path.resolve(String(environment.AIH_INSTALL_ROOT))
  return path.resolve(__dirname, '..', '..')
}

function resolveDataRoot(installRoot, env) {
  const environment = env || process.env
  return environment.DSH_HOME ? path.resolve(environment.DSH_HOME) : path.join(installRoot, 'data')
}

/**
 * Create the Controller core. Pure JS, no Cordis dependency: the host plugin
 * provides it as a service, and bare (non-Cordis) unit harnesses embed it.
 */
function createControllerCore(options = {}) {
  const env = options.env || process.env
  const installRoot = options.installRoot || resolveInstallRoot(env)
  const dataRoot = options.dataRoot || resolveDataRoot(installRoot, env)
  const log = typeof options.log === 'function' ? options.log : () => {}
  const legacy = options.legacyCli || legacyCliModule.createLegacyCli({
    installRoot,
    dataRoot,
    ownerRoot: options.ownerRoot || path.resolve(__dirname, '..', '..'),
    env,
    timeoutMs: options.cliTimeoutMs,
  })
  const strategies = strategyIndexModule.createStrategyIndex({ log })
  const strategyDisposers = []
  for (const module of options.strategies || BUILTIN_STRATEGIES) {
    strategyDisposers.push(strategies.register(module.descriptor, () => module.create()))
  }
  if (options.mandatoryStrategies !== false) strategies.assertMandatory(options.mandatoryStrategies || MANDATORY_STRATEGY_IDS)

  const lanes = new Map()          // laneKey -> tail promise
  const laneDepth = new Map()      // laneKey -> queued + running transitions
  const inFlight = new Set()       // promises of running transitions
  const seenEvents = new Map()     // sessionId -> { keys: Set, order: [] }
  const bridges = new Map()        // mountId -> { plane, attachedAt }
  // P2-A: the single authoritative session-binding writer for this data root.
  const bindings = bindingStoreModule.createBindingStore({
    bindingsPath: path.join(dataRoot, 'routing', 'session-bindings.json'),
    isWriterAttached: (mountId) => !closed && ownershipHeld() && bridges.has(mountId),
    log,
  })
  const metrics = { decisions: 0, decisionRejections: 0, transitions: 0, transitionFailures: 0, maxLaneDepth: 0, eventsClaimed: 0, eventsDeduplicated: 0, admissionsRefused: 0, managedStepsRefused: 0, managedApprovalsAnswered: 0, managedQuestionsRefused: 0, ownerMutationsObserved: 0 }
  let mountSequence = 0
  let closed = false
  let disposal = null
  // Host lifetime ownership of this data root (P2-A primitive). P2-B1: the
  // host plugin creates its core with enforceOwnership, so a host that does
  // not hold the kernel lock (pending, contended or unavailable) is not an
  // authority: plane bridges resolve it as unavailable and refuse every turn
  // and every binding write. Unit-created cores (tests) are not enforced.
  const enforceOwnership = options.enforceOwnership === true
  let ownership = { state: 'not-acquired', enforced: enforceOwnership, lockPath: null, reason: null }
  const ownershipHeld = () => !enforceOwnership || ownership.state === 'held'

  // P2-B2B: durable managed intake (the managed-session registry), live
  // approval broker and the managed task engine. Created by the host plugin
  // (enforced ownership) or explicitly by tests; loaded synchronously here,
  // before the host provides its service or authorizes any remote mutation.
  const managedIntakeEnabled = options.managedIntake === true || (options.managedIntake !== false && enforceOwnership)
  const gates = { hook: { ok: false, reason: 'not-verified' }, policyInstalled: false, fetchGuardInstalled: false, brokerInstalled: false, routeGuards: new Set(), workspaceGuardInstalled: false, dshServicesReady: options.dshServicesReady === true }
  let managedPorts = null
  let intakeStore = null
  let broker = null
  let managedTasks = null
  const qualifiedPlatforms = options.qualifiedPlatforms || QUALIFIED_PLATFORMS
  if (managedIntakeEnabled) {
    intakeStore = intakeStoreModule.createIntakeStore({ dataRoot, canWrite: () => !closed && (enforceOwnership ? ownership.state === 'held' : options.managedIntake === true), log })
    intakeStore.load()
    broker = brokerModule.createApprovalBroker({ log })
    const port = (name) => (...args) => {
      if (!managedPorts || typeof managedPorts[name] !== 'function') throw new ControllerError('managed-port-unavailable', name)
      return managedPorts[name](...args)
    }
    managedTasks = managedTasksModule.createManagedTasks({
      store: intakeStore,
      broker,
      activation: () => activation(),
      log,
      ports: Object.fromEntries(['resolveWorkspace', 'resolveProfile', 'sessionExists', 'createSession', 'prepare', 'prompt', 'flush', 'readDurable', 'cancelTurn', 'lastReply'].map((name) => [name, port(name)])),
    })
  }

  // Resume pending intents the first time activation becomes active (gates
  // may complete after reconciliation, e.g. the route plugin attaching later).
  let resumed = false
  function maybeResume() {
    if (resumed || !managedTasks || !managedTasks.reconciled || !activation().active) return
    resumed = true
    managedTasks.resumePending().catch((error) => log({ event: 'managed-resume-failed', error: String(error && error.message ? error.message : error) }))
  }

  /**
   * Managed admission activation. Active only when EVERY gate holds; there is
   * no runtime switch, environment variable or debug flag that bypasses one.
   */
  function activation() {
    const problems = []
    if (!intakeStore) problems.push('managed-intake-not-configured')
    if (closed) problems.push('controller-closed')
    if (!enforceOwnership || ownership.state !== 'held') problems.push('ownership-not-held-and-enforced')
    if (intakeStore && intakeStore.health().state !== 'ok') problems.push('intake-store-' + intakeStore.health().state)
    if (!gates.hook.ok) problems.push('gateway-hook-unverified:' + gates.hook.reason)
    if (!gates.policyInstalled) problems.push('gateway-policy-not-installed')
    if (!gates.fetchGuardInstalled) problems.push('fetch-route-guard-not-installed')
    if (!gates.brokerInstalled) problems.push('approval-broker-not-installed')
    if (gates.routeGuards.size === 0) problems.push('nexus-route-guard-not-attached')
    if (!gates.workspaceGuardInstalled) problems.push('workspace-guard-not-installed')
    if (!managedPorts) problems.push('managed-ports-unbound')
    if (!gates.dshServicesReady) problems.push('dsh-session-services-unavailable')
    if (!managedTasks || !managedTasks.reconciled) problems.push('intake-not-reconciled')
    if (!qualifiedPlatforms.includes(process.platform)) problems.push('platform-not-qualified:' + process.platform)
    return Object.freeze({ active: problems.length === 0, problems: Object.freeze(problems) })
  }

  // Controller admission for Nexus-managed sessions (P2-A gate, P2-B1
  // lineage/approval/question coverage). Managed admission stays DISABLED.
  //   - inference/tools: every agent/pre-step of a managed session is refused
  //     (prevention at the effect seam every route crosses);
  //   - subagent children (`origin: 'subagent'` with `parentSession`) inherit
  //     their parent's managed status (prevention); user forks do not (a fork
  //     is a new, independent ordinary session: authorized delegation);
  //   - approval/request and user-questions/request for a managed session are
  //     answered by the Controller (rejected while disabled) BEFORE the Web
  //     remote forwarder, so no owner peer can answer them (prevention);
  //   - every other owner mutation of a managed session that DSH 0.2.2 cannot
  //     intercept per session is recorded for reconciliation.
  const managed = new Map()
  const reconciliation = []
  const RECONCILIATION_LIMIT = 1000
  const sessionLookup = typeof options.sessionLookup === 'function' ? options.sessionLookup : () => undefined
  function headerOf(sessionOrId) {
    if (sessionOrId && typeof sessionOrId === 'object') return { id: sessionOrId.id, header: sessionOrId.header || {} }
    const session = typeof sessionOrId === 'string' ? sessionLookup(sessionOrId) : undefined
    return { id: sessionOrId, header: (session && session.header) || {} }
  }
  function managedRootOf(sessionOrId) {
    let current = headerOf(sessionOrId)
    for (let depth = 0; depth < 16 && current && typeof current.id === 'string'; depth += 1) {
      if (managed.has(current.id) || (intakeStore && (intakeStore.bySessionId(current.id) || intakeStore.isQuarantined(current.id)))) return current.id
      if (current.header.origin !== 'subagent' || typeof current.header.parentSession !== 'string') return null
      current = headerOf(current.header.parentSession)
    }
    return null
  }
  function activeManagedSessions() {
    if (!intakeStore) return [...managed.keys()]
    const ids = new Set(managedTasks.activeSessionIds())
    for (const record of intakeStore.pending()) ids.add(record.sessionId)
    for (const id of managed.keys()) ids.add(id)
    return [...ids]
  }
  const admission = Object.freeze({
    get state() { return activation().active ? 'active' : 'disabled' },
    activation: () => activation(),
    activeManagedSessions,
    isManagedTaskInstance(taskInstanceId) { return Boolean(intakeStore && intakeStore.list().some((record) => record.taskInstanceId === taskInstanceId)) },
    register(sessionId, info = {}) {
      assertOpen('managed session registration')
      if (typeof sessionId !== 'string' || sessionId === '') throw new ControllerError('admission-session-invalid', 'a managed session needs an id')
      managed.set(sessionId, { taskKey: info.taskKey || null, registeredAt: new Date().toISOString() })
      log({ event: 'managed-session-registered', sessionId })
    },
    unregister(sessionId) { return managed.delete(sessionId) },
    isManaged(sessionOrId) { return managedRootOf(sessionOrId) !== null },
    rootOf(sessionOrId) { return managedRootOf(sessionOrId) },
    /**
     * Async admission ticket for one agent/pre-step (host gate and plane
     * bridges alike; idempotent per turn). Unmanaged sessions pass.
     */
    async admit(session, payload) {
      const root = managedRootOf(session)
      if (root === null) return { allowed: true, code: null }
      if (!managedTasks || closed) { metrics.managedStepsRefused += 1; return { allowed: false, code: 'managed-admission-disabled' } }
      const verdict = await managedTasks.admitStep(root, session && typeof session === 'object' ? session : { id: root }, payload)
      if (!verdict.allowed) metrics.managedStepsRefused += 1
      return verdict
    },
    /**
     * Synchronous plane-bridge check. A managed step passes only after the host
     * admission gate issued a ticket for the live turn (managed-tasks.admitStep).
     */
    check(sessionOrId) {
      const root = managedRootOf(sessionOrId)
      if (root === null) return { allowed: true, code: null }
      if (managedTasks && managedTasks.stepAdmitted(root)) return { allowed: true, code: null }
      metrics.managedStepsRefused += 1
      return { allowed: false, code: activation().active ? 'managed-turn-not-admitted' : 'managed-admission-disabled' }
    },
    /** approval/request outcome for a managed session (never forwarded to peers). */
    approvalOutcome(sessionOrId) {
      if (managedRootOf(sessionOrId) === null) return null
      metrics.managedApprovalsAnswered += 1
      return 'rejected'
    },
    questionRefusal(sessionOrId) {
      if (managedRootOf(sessionOrId) === null) return null
      metrics.managedQuestionsRefused += 1
      return 'managed-admission-disabled'
    },
    /** Record an owner mutation the Controller could not prevent (reconciliation input). */
    recordOwnerMutation(sessionOrId, kind, detail = {}) {
      const root = managedRootOf(sessionOrId)
      if (root === null) return false
      const record = Object.freeze({ at: new Date().toISOString(), sessionId: headerOf(sessionOrId).id, managedRoot: root, kind, ...detail })
      reconciliation.push(record)
      while (reconciliation.length > RECONCILIATION_LIMIT) reconciliation.shift()
      metrics.ownerMutationsObserved += 1
      log({ event: 'managed-owner-mutation-observed', ...record })
      return true
    },
    reconciliationLog() { return reconciliation.slice() },
  })

  function assertOpen(purpose) {
    if (closed) {
      metrics.admissionsRefused += 1
      throw new ControllerError('nexus-controller-closed', `the Nexus Controller is shutting down; ${purpose} refused`)
    }
  }

  /**
   * Strategy dispatch. Resolves the strategy serving `engine`, asks it for a
   * decision and validates it against contract major 1. Exactly one decision
   * is consumed per event in P1. Missing strategy, unsupported contract and
   * forbidden decisions (e.g. a completion attempt) throw typed errors.
   */
  function decide(engine, view, event) {
    assertOpen('strategy dispatch')
    const entry = strategies.forEngine(engine)
    let decisions
    try {
      decisions = entry.implementation.decide(Object.freeze({ ...(view || {}), engine }), Object.freeze({ ...(event || {}) }))
    } catch (error) {
      metrics.decisionRejections += 1
      throw new ControllerError('strategy-decide-failed', `${entry.descriptor.id}: ${String(error && error.message ? error.message : error)}`)
    }
    if (!Array.isArray(decisions) || decisions.length !== 1) {
      metrics.decisionRejections += 1
      throw new ControllerError('strategy-decision-invalid', `${entry.descriptor.id}: expected exactly one decision for ${event && event.type}`)
    }
    let decision
    try {
      decision = strategyIndexModule.validateDecision(entry.descriptor.id, decisions[0])
    } catch (error) {
      metrics.decisionRejections += 1
      throw error
    }
    metrics.decisions += 1
    return Object.freeze({ ...decision, strategyId: entry.descriptor.id, contractMajor: entry.descriptor.contractMajor })
  }

  /**
   * Serialize one authoritative task/attempt transition per lane (task
   * generation). The work itself still runs through the legacy writer
   * (Task.ps1/TaskController.ps1, which keeps its own ledger mutex); the lane
   * orders writers inside this host so concurrent observers and bridge mounts
   * can never interleave transitions of the same generation.
   */
  function transition(laneKey, label, work) {
    assertOpen(`transition ${label}`)
    if (typeof laneKey !== 'string' || laneKey === '') throw new ControllerError('transition-lane-invalid', `transition ${label} has no task lane`)
    if (typeof work !== 'function') throw new ControllerError('transition-work-invalid', `transition ${label} has no work`)
    const previous = lanes.get(laneKey) || Promise.resolve()
    const depth = (laneDepth.get(laneKey) || 0) + 1
    laneDepth.set(laneKey, depth)
    if (depth > metrics.maxLaneDepth) metrics.maxLaneDepth = depth
    const run = previous.catch(() => undefined).then(async () => {
      metrics.transitions += 1
      try {
        return await work()
      } catch (error) {
        metrics.transitionFailures += 1
        throw error
      }
    })
    const tail = run.catch(() => undefined)
    lanes.set(laneKey, tail)
    inFlight.add(tail)
    tail.then(() => {
      inFlight.delete(tail)
      const remaining = (laneDepth.get(laneKey) || 1) - 1
      if (remaining <= 0) laneDepth.delete(laneKey); else laneDepth.set(laneKey, remaining)
      if (lanes.get(laneKey) === tail) lanes.delete(laneKey)
    })
    return run
  }

  /**
   * Claim a DSH session event for Controller side effects. Returns true the
   * first time (sessionId, seq, type) is seen, false for a duplicate
   * delivery. Events without a numeric seq are never deduplicated.
   */
  function claimEvent(sessionId, event) {
    if (!event || typeof event !== 'object') return false
    if (typeof sessionId !== 'string' || !Number.isSafeInteger(event.seq)) { metrics.eventsClaimed += 1; return true }
    const key = event.seq + ':' + String(event.type || '')
    let record = seenEvents.get(sessionId)
    if (!record) { record = { keys: new Set(), order: [] }; seenEvents.set(sessionId, record) }
    if (record.keys.has(key)) { metrics.eventsDeduplicated += 1; return false }
    record.keys.add(key)
    record.order.push(key)
    while (record.order.length > EVENT_DEDUP_WINDOW) record.keys.delete(record.order.shift())
    metrics.eventsClaimed += 1
    return true
  }

  function forgetSession(sessionId) { seenEvents.delete(sessionId) }

  /** Register one scoped plane bridge (an `aih-controller` mount). */
  function attachBridge(info = {}) {
    assertOpen('bridge attach')
    const mountId = 'bridge-' + (++mountSequence)
    bridges.set(mountId, { plane: typeof info.plane === 'string' ? info.plane : 'unknown', attachedAt: new Date().toISOString() })
    log({ event: 'controller-bridge-attached', mountId, plane: info.plane || 'unknown' })
    let detached = false
    const detach = function detach() {
      if (detached) return false
      detached = true
      // Disposal already released every attachment: nothing left to detach.
      if (!bridges.delete(mountId)) return false
      log({ event: 'controller-bridge-detached', mountId, plane: info.plane || 'unknown' })
      return true
    }
    // The mount id is the bridge's binding-writer identity (P2-A).
    detach.mountId = mountId
    return detach
  }

  function readiness(context = {}) {
    const attachedPlanes = [...new Set([...bridges.values()].map((bridge) => bridge.plane))].sort()
    const strategyRows = closed ? [] : strategies.readiness({ requirePlanes: Boolean(context.requirePlanes), attachedPlanes })
    const problems = []
    if (closed) problems.push('controller-closed')
    if (!ownershipHeld()) problems.push('host-ownership-' + ownership.state)
    for (const id of MANDATORY_STRATEGY_IDS) {
      const row = strategyRows.find((item) => item.id === id)
      if (!row) problems.push('strategy-missing:' + id)
      else if (!row.ready) problems.push('strategy-not-ready:' + id + ':' + (row.reason || 'unknown'))
    }
    return Object.freeze({
      ready: problems.length === 0,
      problems,
      contractMajor: CONTROLLER_CONTRACT_MAJOR,
      build: CONTROLLER_BUILD,
      strategies: strategyRows,
      bridges: [...bridges.entries()].map(([mountId, bridge]) => ({ mountId, plane: bridge.plane })),
      attachedPlanes,
      legacyCli: { pwshHost: legacy.pwshHost, toolchainRoot: legacy.toolchainRoot, timeoutMs: legacy.timeoutMs },
      ownership: Object.freeze({ ...ownership }),
      transport,
      managedAdmission: admission.state,
      managedActivation: activation(),
      intakeStore: intakeStore ? { dir: intakeStore.dir, health: intakeStore.health(), records: intakeStore.list().length } : null,
      bindingStore: { path: bindings.bindingsPath, closed: bindings.closed },
    })
  }

  function snapshotMetrics() {
    return Object.freeze({ ...metrics, lanes: lanes.size, bridges: bridges.size, legacyCli: legacy.stats(), bindingStore: bindings.metrics(), managedTasks: managedTasks ? managedTasks.metrics() : null, broker: broker ? broker.metrics() : null })
  }

  /**
   * Close admission first, then await in-flight transitions, then release
   * strategies. Idempotent; returns the same promise on repeated calls.
   */
  function dispose() {
    if (disposal) return disposal
    closed = true
    bindings.close()
    disposal = (async () => {
      await Promise.allSettled([...inFlight])
      for (const disposeStrategy of strategyDisposers.splice(0).reverse()) disposeStrategy()
      strategies.dispose()
      seenEvents.clear()
      bridges.clear()
      managed.clear()
      if (broker) broker.dispose()
      if (intakeStore) intakeStore.close()
      log({ event: 'controller-disposed' })
    })()
    return disposal
  }

  let transport = { state: 'none' }
  function setTransport(next) { transport = Object.freeze({ ...next }) }
  function setOwnership(next) {
    ownership = Object.freeze({ state: next.state, enforced: enforceOwnership, lockPath: next.lockPath || null, reason: next.reason || null, generation: next.generation || null })
    log({ event: 'host-ownership', state: ownership.state, lockPath: ownership.lockPath, reason: ownership.reason })
  }

  const service = {
    contractMajor: CONTROLLER_CONTRACT_MAJOR,
    build: CONTROLLER_BUILD,
    installRoot,
    dataRoot,
    legacy,
    strategies,
    bindings,
    decide,
    transition,
    claimEvent,
    forgetSession,
    attachBridge,
    readiness,
    metrics: snapshotMetrics,
    dispose,
    admission,
    setOwnership,
    get ownership() { return ownership },
    setTransport,
    get transport() { return transport },
    workspaceAuthorizer: typeof options.workspaceAuthorizer === 'function' ? options.workspaceAuthorizer : null,
    workspaceRegistrar: typeof options.workspaceRegistrar === 'function' ? options.workspaceRegistrar : null,
    credentials: options.credentials && typeof options.credentials === 'object' ? options.credentials : null,
    get ownershipHeld() { return ownershipHeld() },
    get closed() { return closed },
    intake: intakeStore,
    broker,
    managedTasks,
    activation,
    /** Host-only: bind the DSH operations the managed engine may perform (once). */
    bindManagedPorts(ports) {
      if (managedPorts) throw new ControllerError('managed-ports-bound', 'managed ports are already bound')
      managedPorts = Object.freeze({ ...ports })
    },
    /** Host-only gate evidence. The hook gate takes a verification result object. */
    setManagedGate(name, value) {
      if (name === 'hook') { gates.hook = Object.freeze({ ok: value && value.ok === true, reason: value && value.reason ? String(value.reason) : (value && value.ok ? 'verified' : 'unknown'), digest: value && value.digest || null, build: value && value.build || null, detail: value && value.detail || null }); log({ event: 'managed-gate', gate: 'hook', ...gates.hook }); return }
      if (!['policyInstalled', 'fetchGuardInstalled', 'brokerInstalled', 'workspaceGuardInstalled', 'dshServicesReady'].includes(name)) throw new ControllerError('managed-gate-unknown', name)
      gates[name] = value === true
      maybeResume()
    },
    /** Host-only: after reconciliation, resume pending intents once activation is active. */
    resumeManaged() { maybeResume() },
    /** A `/nexus/*` route plugin announces its guard; returns the detach function. */
    attachRouteGuard(owner) {
      const token = Symbol(String(owner || 'route-guard'))
      gates.routeGuards.add(token)
      maybeResume()
      return () => gates.routeGuards.delete(token)
    },
    routeVerdict(route, input) { return gatewayPolicyModule.nexusRouteVerdict(service, route, input) },
    get managedGates() { return { hook: gates.hook, policyInstalled: gates.policyInstalled, fetchGuardInstalled: gates.fetchGuardInstalled, brokerInstalled: gates.brokerInstalled, routeGuards: gates.routeGuards.size, workspaceGuardInstalled: gates.workspaceGuardInstalled, dshServicesReady: gates.dshServicesReady } },
  }
  service.tasks = taskApiModule.createTaskApi({ core: service })
  return Object.freeze(service)
}

/**
 * How a plane bridge reaches the Controller.
 *  - Inside a real Cordis composition (a Cordis context: `ctx.reflect.get`,
 *    the source of the `ctx.get` mixin, exists) the bridge resolves
 *    the host `nexusController` service at every authority point WITHOUT
 *    injecting it: if the host service is absent, closed or incompatible the
 *    bridge stays mounted and refuses (fail closed) instead of being unloaded
 *    and letting turns run without Controller policy.
 *  - A plain object that is not a Cordis context (legacy unit harnesses that
 *    call apply() directly, even when they stub `get` for other services)
 *    embeds a private core with identical semantics.
 */
function isCordisContext(ctx) {
  try {
    return Boolean(ctx && typeof ctx.get === 'function' && ctx.reflect && typeof ctx.reflect.get === 'function')
  } catch {
    return false
  }
}

function resolveControllerAccess(ctx, embeddedOptions) {
  if (isCordisContext(ctx)) {
    return Object.freeze({
      mode: 'host',
      // Registration only (bridge attachment): the live, compatible host
      // service regardless of ownership. Never used for authority.
      peek() {
        let service
        try { service = ctx.get(CONTROLLER_SERVICE) } catch { service = undefined }
        return service && service.contractMajor === CONTROLLER_CONTRACT_MAJOR && !service.closed ? service : null
      },
      get() {
        let service
        try { service = ctx.get(CONTROLLER_SERVICE) } catch { service = undefined }
        if (!service) return { core: null, reason: 'nexus-controller-unavailable' }
        if (service.contractMajor !== CONTROLLER_CONTRACT_MAJOR) return { core: null, reason: 'nexus-controller-contract-unsupported' }
        if (service.closed) return { core: null, reason: 'nexus-controller-closed' }
        if (service.ownershipHeld === false) return { core: null, reason: 'nexus-host-ownership-' + String(service.ownership && service.ownership.state) }
        return { core: service, reason: null }
      },
    })
  }
  const core = createControllerCore(embeddedOptions)
  return Object.freeze({ mode: 'embedded', embedded: core, peek() { return core.closed ? null : core }, get() { return core.closed ? { core: null, reason: 'nexus-controller-closed' } : { core, reason: null } } })
}

function controllerLog(dataRoot) {
  const fs = require('node:fs')
  return (entry) => {
    try {
      const logDir = path.join(dataRoot, 'logs')
      fs.mkdirSync(logDir, { recursive: true })
      fs.appendFileSync(path.join(logDir, 'nexus-controller.log'), JSON.stringify({ ts: new Date().toISOString(), plugin: 'nexus-controller', ...entry }) + '\n')
    } catch { /* logging never breaks the host */ }
  }
}

// Owner mutations of a managed session that DSH 0.2.2 commits without a
// per-session authorization seam. Observed post-commit for reconciliation.
const RECONCILED_EVENT_TYPES = Object.freeze({
  'session/renamed': 'rename', 'session/title': 'rename', 'title/changed': 'rename',
  'agent-preset/selected': 'preset-select', 'model/selected': 'model-select', 'agent/model-selected': 'model-select',
  'inbox/updated': 'queue-update', 'queue/updated': 'queue-update',
})

/**
 * Verify the proposed `gateway/authorize` hook on THIS running host: the
 * installed gateway build must be allowlisted AND a live owner call through
 * the gateway must be refused by a temporary self-test listener. Read-only
 * (`session/list`); never throws. Absent hook => { ok: false }.
 */
async function verifyGatewayHook(ctx, appRoot) {
  const crypto = require('node:crypto')
  const fs = require('node:fs')
  const { createRequire } = require('node:module')
  const { pathToFileURL } = require('node:url')
  let appRequire
  let gatewayFile
  try {
    appRequire = createRequire(path.join(appRoot, 'package.json'))
    gatewayFile = appRequire.resolve('@deepseek-ai/dsh-api-gateway')
  } catch { return { ok: false, reason: 'gateway-package-unresolvable' } }
  let digest
  try { digest = crypto.createHash('sha256').update(fs.readFileSync(gatewayFile)).digest('hex') } catch { return { ok: false, reason: 'gateway-package-unreadable' } }
  const build = GATEWAY_HOOK_DIGESTS[digest]
  if (!build) return { ok: false, reason: 'gateway-build-not-allowlisted', digest }
  let gateway
  try { gateway = ctx.get('typertGateway') } catch { gateway = undefined }
  if (!gateway || typeof gateway.invoke !== 'function') return { ok: false, reason: 'gateway-service-unavailable', digest, build }
  let Peer
  try { ({ Peer } = await import(pathToFileURL(appRequire.resolve('@deepseek-ai/dsh-client-connection')).href)) } catch { return { ok: false, reason: 'connection-package-unresolvable', digest, build } }
  const nonce = 'nexus-self-test:' + crypto.randomBytes(12).toString('hex')
  let armed = true
  let observed = null
  const dispose = ctx.on('gateway/authorize', (request) => {
    if (!armed || request.action !== 'session/list' || !request.principal || request.principal.kind !== 'owner') return undefined
    observed = { frozen: Object.isFrozen(request) && Object.isFrozen(request.args), transport: request.transport }
    return { kind: 'deny', reason: nonce }
  })
  const peer = new Peer(ctx.root, { principal: { kind: 'owner' } })
  try {
    await gateway.invoke({ peer, namespace: 'session', method: 'list', args: { _request: {} } })
    return { ok: false, reason: 'gateway-hook-inert', digest, build }
  } catch (error) {
    const reason = error && error.details && error.details.reason
    if (reason !== nonce || !observed || !observed.frozen || observed.transport !== 'unary') return { ok: false, reason: 'gateway-hook-misbehaved', digest, build, detail: { code: error && error.code ? String(error.code) : null, observed: Boolean(observed), frozen: observed ? observed.frozen : null, transport: observed ? observed.transport : null, message: String(error && error.message ? error.message : error).slice(0, 200) } }
    return { ok: true, reason: 'verified', digest, build }
  } finally {
    armed = false
    dispose()
    try { await peer.dispose() } catch { /* already disposed */ }
  }
}

/** Cordis host plugin: exactly one `nexusController` service per host. */
function apply(ctx) {
  const installRoot = resolveInstallRoot()
  const dataRoot = resolveDataRoot(installRoot)
  const log = controllerLog(dataRoot)
  const sessions = () => { try { return ctx.get('sessions') } catch { return undefined } }
  const core = createControllerCore({
    installRoot, dataRoot, log, enforceOwnership: true,
    sessionLookup: (id) => { const store = sessions(); try { return store && typeof store.get === 'function' ? store.get(id) : undefined } catch { return undefined } },
    // DSH's credentials controller (the Models page service); values pass
    // through, never logged or returned.
    credentials: {
      describe: (refs) => { const c = ctx.get('credentialsController'); if (!c) throw new Error('credentials controller unavailable'); return c.describe(refs) },
      set: (ref, value) => { const c = ctx.get('credentialsController'); if (!c) throw new Error('credentials controller unavailable'); return c.set(ref, value) },
      unset: (ref) => { const c = ctx.get('credentialsController'); if (!c) throw new Error('credentials controller unavailable'); return c.unset(ref) },
    },
    workspaceRegistrar: async (workspacePath) => {
      let registry
      try { registry = ctx.get('workspaceRegistry') } catch { registry = undefined }
      if (!registry || typeof registry.create !== 'function') throw new Error('the DSH workspace registry is unavailable')
      const existing = typeof registry.resolveByPath === 'function' ? await registry.resolveByPath(workspacePath).catch(() => undefined) : undefined
      const workspace = existing || await registry.create(workspacePath, path.basename(workspacePath))
      return { workspaceId: workspace.id ?? workspace.workspaceId, path: workspace.path, disposition: existing ? 'existing' : 'registered' }
    },
    workspaceAuthorizer: async (workspacePath) => {
      let registry
      try { registry = ctx.get('workspaceRegistry') } catch { registry = undefined }
      if (!registry || typeof registry.resolveByPath !== 'function') return false
      try { return Boolean(await registry.resolveByPath(workspacePath)) } catch { return false }
    },
  })
  // Host lifetime ownership (P2-B1: enforced). Acquired without stealing; a
  // brief bounded retry absorbs a launcher probe that holds the lock for a few
  // microseconds. Contended or unavailable => this host refuses (fail closed).
  const appRoot = process.env.AIH_HOST_APP || path.join(installRoot, 'app')
  let ipcServer = null
  // The DSH services the managed engine operates through. Reconciliation and
  // the hook self-test wait for them; their loss deactivates admission.
  let markServicesReady
  const servicesReady = new Promise((resolve) => { markServicesReady = resolve })
  let markDisposed
  const disposed = new Promise((resolve) => { markDisposed = resolve })
  if (core.managedTasks) {
    ctx.inject(['sessionController', 'sessionPersistence', 'sessions', 'workspaceRegistry', 'typertGateway'], (servicesCtx) => {
      core.setManagedGate('dshServicesReady', true)
      markServicesReady(true)
      servicesCtx.effect(() => () => { if (!core.closed) core.setManagedGate('dshServicesReady', false) }, 'nexus-controller: managed DSH services')
    })
  }
  const acquisition = (async () => {
    let result
    for (let attempt = 0; attempt < 5; attempt += 1) {
      result = await hostOwnershipModule.acquireHostOwnership({ dataRoot, appRoot, build: CONTROLLER_BUILD })
      if (result.state !== 'contended') break
      await new Promise((resolve) => setTimeout(resolve, 100 * (attempt + 1)))
    }
    if (core.closed) { await result.release(); return result }
    core.setOwnership(result)
    if (result.state === 'held' && process.env.NEXUS_IPC !== '0') {
      try {
        ipcServer = await ipcModule.startIpcServer({ core, dataRoot, generation: result.generation, log })
        core.setTransport({ state: 'listening', endpoint: ipcServer.endpoint, protocol: ipcModule.PROTOCOL })
      } catch (error) {
        core.setTransport({ state: 'unavailable', reason: String(error && error.message ? error.message : error) })
      }
    }
    if (result.state === 'held' && core.managedTasks && !core.closed && await Promise.race([servicesReady, disposed]) === true && !core.closed) {
      // Hook first (a failure keeps submit fail-closed), then reconcile every
      // pending intake before activation can become active.
      core.setManagedGate('hook', await verifyGatewayHook(ctx, appRoot))
      try { await core.managedTasks.reconcile() } catch (error) { log({ event: 'managed-reconcile-failed', error: String(error && error.message ? error.message : error) }) }
      const gate = core.activation()
      log({ event: 'managed-activation', active: gate.active, problems: gate.problems })
      core.resumeManaged()
    }
    return result
  })().catch((error) => {
    const result = { state: 'unavailable', reason: String(error && error.message ? error.message : error), release: async () => false }
    core.setOwnership(result)
    return result
  })
  // Composite lifecycle: close admission and the binding store, drain, stop
  // IPC, then release ownership last.
  ctx.effect(() => async () => {
    markDisposed(false)
    await core.dispose()
    const result = await acquisition
    if (ipcServer) { try { await ipcServer.close() } catch { /* already closed */ } }
    await result.release()
  }, 'nexus-controller core')
  ctx.provide(CONTROLLER_SERVICE, core)

  // ── P2-B2B host wiring ────────────────────────────────────────────────
  const sessionsService = () => { try { return ctx.get('sessions') } catch { return undefined } }
  const liveSession = (id) => { const store = sessionsService(); try { return store && typeof store.get === 'function' ? store.get(id) : undefined } catch { return undefined } }
  const service = (name) => { try { return ctx.get(name) } catch { return undefined } }
  const workspaceSessions = (workspaceId) => {
    const registry = service('workspaceRegistry')
    try {
      const workspace = registry && typeof registry.get === 'function' ? registry.get(workspaceId) : undefined
      return workspace && workspace.sessionIds ? [...workspace.sessionIds] : []
    } catch { return [] }
  }
  if (core.managedTasks) {
    const nexusProfiles = require('../Nexus-Profiles.cjs')
    core.bindManagedPorts({
      async resolveWorkspace(workspacePath) {
        const registry = service('workspaceRegistry')
        if (!registry || typeof registry.resolveByPath !== 'function' || !path.isAbsolute(workspacePath)) return null
        try {
          const workspace = await registry.resolveByPath(workspacePath)
          if (!workspace) return null
          return { workspaceId: workspace.id ?? workspace.workspaceId, path: workspace.path }
        } catch { return null }
      },
      // The preset's active Nexus profile under the existing precedence
      // contract (same resolver the GUI uses); must match the preset's engine.
      resolveProfile(preset) {
        try {
          const active = nexusProfiles.resolveActiveNexusProfile(installRoot, preset)
          const engine = preset === 'aih-muse' ? 'muse' : 'dual'
          return active && active.engine === engine && active.runnable !== false ? active.id : null
        } catch { return null }
      },
      async sessionExists(sessionId) {
        if (liveSession(sessionId)) return true
        const persistence = service('sessionPersistence')
        return Boolean(persistence && await persistence.stat(sessionId))
      },
      async createSession(request) {
        const controller = service('sessionController')
        if (!controller) throw new ControllerError('session-controller-unavailable', 'DSH session controller unavailable')
        const created = await controller.create({ sessionId: request.sessionId, workspaceId: request.workspaceId, agentPreset: request.agentPreset })
        return created && created.sessionId
      },
      prepare(request) {
        return ctx.waterfall('nexus/session-prepare', request, () => { throw new ControllerError('session-prepare-unavailable', 'no plane bridge serves session preparation') })
      },
      async prompt(request) {
        const controller = service('sessionController')
        if (!controller) throw new ControllerError('managed-port-unavailable', 'DSH session controller unavailable')
        await controller.prompt({ requestId: request.requestId, sessionId: request.sessionId, mode: 'queue', content: [{ type: 'text', text: request.text }] }, new AbortController().signal)
      },
      async flush(sessionId) {
        const session = liveSession(sessionId)
        const store = sessionsService()
        if (session && store && typeof store.flush === 'function') await store.flush(session)
      },
      async readDurable(sessionId) {
        const persistence = service('sessionPersistence')
        if (!persistence) throw new ControllerError('session-persistence-unavailable', 'no durable session reader')
        const handle = await persistence.open(sessionId, 'read')
        try {
          const result = await handle.read(0)
          return Array.isArray(result) ? result : (result && Array.isArray(result.events) ? result.events : null)
        } finally { await handle.close() }
      },
      // The session's last assistant text (live log, else the durable log).
      async lastReply(sessionId) {
        let events = null
        const live = liveSession(sessionId)
        if (live) { try { events = require('../Dsh-SessionEvents.cjs').sessionEvents(live) } catch { events = null } }
        if (!Array.isArray(events)) {
          const persistence = service('sessionPersistence')
          if (!persistence) return null
          try {
            const handle = await persistence.open(sessionId, 'read')
            try { const result = await handle.read(0); events = Array.isArray(result) ? result : (result && result.events) } finally { await handle.close() }
          } catch { return null }
        }
        if (!Array.isArray(events)) return null
        for (let index = events.length - 1; index >= 0; index -= 1) {
          const event = events[index]
          if (!event || event.type !== 'assistant/message' || !event.data || !event.data.message) continue
          const text = (Array.isArray(event.data.message.content) ? event.data.message.content : []).filter((block) => block && block.type === 'text' && typeof block.text === 'string').map((block) => block.text).join('\n').trim()
          if (text) return { text: text.length > 8000 ? text.slice(0, 8000) + '\n…(truncated)' : text, at: typeof event.time === 'number' ? new Date(event.time).toISOString() : null, seq: event.seq }
        }
        return null
      },
      async cancelTurn(sessionId) {
        const controller = service('sessionController')
        if (controller) controller.cancel({ sessionId })
      },
    })

    // Product gateway policy (inert until DSH emits `gateway/authorize`) and
    // the Connection fetch-route guard; both registered before the service is
    // provided, so no remote mutation is served without them.
    const policy = gatewayPolicyModule.createGatewayPolicy({ controller: () => core, sessionOf: liveSession, workspaceSessions })
    ctx.on('gateway/authorize', (request) => policy.decide(request))
    core.setManagedGate('policyInstalled', true)
    ctx.on('connection/request', (req, res, next) => {
      let verdict
      try { verdict = policy.fetchRouteVerdict(req.method, new URL(req.url, 'http://nexus.invalid')) } catch { verdict = { kind: 'deny', reason: 'nexus-request-unparseable' } }
      if (verdict) { res.writeHead(403, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }); res.end(JSON.stringify({ ok: false, error: verdict.reason })); return undefined }
      return next()
    }, { prepend: true })
    core.setManagedGate('fetchGuardInstalled', true)
  }

  // Managed-session effect gate (independent of the plane bridges): the
  // admission ticket, plus workspace exclusivity for ordinary sessions.
  ctx.on('agent/pre-step', async (payload, next) => {
    const session = payload && payload.agent && payload.agent.session
    if (session && typeof session.id === 'string') {
      const root = core.admission.rootOf(session)
      if (root !== null) {
        const verdict = await core.admission.admit(session, payload)
        if (!verdict.allowed) {
          log({ event: 'managed-step-refused', sessionId: session.id, code: verdict.code, gate: 'host' })
          return { kind: 'reject' }
        }
      } else if (core.managedTasks && session.header && typeof session.header.cwd === 'string') {
        // An ordinary session may not write into a workspace while a managed
        // task there is live or pending (cross-session snapshot protection).
        const cwd = path.resolve(session.header.cwd)
        const clash = core.admission.activeManagedSessions().some((id) => { const managedSession = liveSession(id); return managedSession && managedSession.header && typeof managedSession.header.cwd === 'string' && path.resolve(managedSession.header.cwd) === cwd })
        if (clash) { log({ event: 'workspace-exclusive-step-refused', sessionId: session.id, gate: 'host' }); return { kind: 'reject' } }
      }
    }
    return next()
  }, { prepend: true })
  if (core.managedTasks) core.setManagedGate('workspaceGuardInstalled', true)

  // Approvals and questions of managed sessions are answered here, before the
  // Web remote forwarder (dsh-api-remotes), so owner peers never receive them.
  // With activation active they are offered through the broker to GUI and CLI
  // task clients; otherwise they are rejected.
  ctx.on('approval/request', async (request, next) => {
    const session = request && request.agent && request.agent.session
    const root = session ? core.admission.rootOf(session) : null
    if (root === null) return next()
    const record = core.intake && core.intake.bySessionId(root)
    if (!core.admission.activation().active || !record || !core.managedTasks.isTurnLive(root)) {
      const outcome = core.admission.approvalOutcome(session) || 'rejected'
      log({ event: 'managed-approval-answered', sessionId: session.id, outcome, gate: 'host' })
      return outcome
    }
    const answer = await core.broker.request({
      taskId: record.taskId, sessionId: session.id, kind: 'approval',
      label: String(request.toolName || 'tool') + (request.reason ? ': ' + String(request.reason).slice(0, 300) : ''),
      choices: [{ id: 'allow-once', label: 'Allow once' }, { id: 'reject', label: 'Reject' }],
      signal: request.signal,
    })
    const outcome = answer.choiceId === 'allow-once' ? 'allowed-once' : (answer.reason === 'aborted' ? 'cancelled' : 'rejected')
    log({ event: 'managed-approval-answered', sessionId: session.id, taskId: record.taskId, outcome, reason: answer.reason, gate: 'broker' })
    return outcome
  }, { prepend: true })
  ctx.on('user-questions/request', async (request, next) => {
    const session = request && request.agent && request.agent.session
    const root = session ? core.admission.rootOf(session) : null
    if (root === null) return next()
    const record = core.intake && core.intake.bySessionId(root)
    const questions = request && Array.isArray(request.questions) ? request.questions : []
    const single = questions.length === 1 && Array.isArray(questions[0].options) && questions[0].options.length > 0 && !questions[0].multiSelect
    const refuse = (why) => {
      core.admission.questionRefusal(session)
      log({ event: 'managed-question-refused', sessionId: session.id, reason: why, gate: 'host' })
      const error = new Error('Nexus-managed session: this question cannot be answered through the Nexus task API (' + why + ').')
      error.code = 'NO_PROVIDER'
      return Promise.reject(error)
    }
    if (!core.admission.activation().active || !record || !core.managedTasks.isTurnLive(root)) return refuse('managed-admission-inactive')
    if (!single) return refuse('unsupported-question-shape')
    const question = questions[0]
    const choices = question.options.map((option, index) => ({ id: 'option-' + index, label: String(option.label) }))
    const answer = await core.broker.request({ taskId: record.taskId, sessionId: session.id, kind: 'question', label: String(question.question || '').slice(0, 500), choices, signal: request.signal })
    if (!answer.choiceId) return refuse('unanswered:' + answer.reason)
    const chosen = choices.find((choice) => choice.id === answer.choiceId)
    return { answers: [{ id: question.id, selected: [chosen.label] }] }
  }, { prepend: true })
  if (core.managedTasks) core.setManagedGate('brokerInstalled', true)

  // GUI adapter of the SAME task API (P2-B2B): `/nexus/tasks/v1/<operation>`,
  // admitted exactly like /api (Host/Origin fence + launch-token cookie), the
  // same versioned envelope and field validation as local IPC. The principal is
  // derived from the admitted transport, never from the request.
  const guiPrincipal = Object.freeze({ kind: 'local-owner', via: 'gui', capabilities: Object.freeze(['tasks:read', 'tasks:submit', 'tasks:cancel', 'tasks:respond', 'workspaces:register', 'credentials:read', 'credentials:write']) })
  ctx.inject(['webServer', 'connection'], (webCtx) => {
    const handler = async (req, res) => {
      const reply = (status, body) => { res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }); res.end(JSON.stringify(body)) }
      const admitted = webCtx.connection && typeof webCtx.connection.admit === 'function' ? webCtx.connection.admit(req) : { rejection: 503 }
      if (!admitted || 'rejection' in admitted) return reply(admitted ? admitted.rejection : 503, { ok: false, error: 'not-admitted' })
      if (req.method !== 'POST') return reply(405, { ok: false, error: 'method-not-allowed' })
      const operation = new URL(req.url || '/', 'http://nexus.invalid').pathname.slice('/nexus/tasks/v1/'.length)
      let size = 0
      const chunks = []
      for await (const chunk of req) { size += chunk.length; if (size > ipcModule.MAX_FRAME_BYTES) return reply(413, { ok: false, error: 'request-too-large' }); chunks.push(chunk) }
      let message
      try { message = JSON.parse(Buffer.concat(chunks).toString('utf8')) } catch { return reply(400, { schemaVersion: 1, ok: false, error: { code: 'USAGE', message: 'invalid JSON', retryable: false } }) }
      const checked = ipcModule.validateRequest(message && typeof message === 'object' && !Array.isArray(message) ? { ...message, operation } : message)
      if (checked.error) return reply(200, checked.error)
      if (core.closed) return reply(200, { schemaVersion: 1, ok: false, requestId: checked.request.requestId, error: { code: 'HOST_NOT_READY', message: 'The Nexus Controller is shutting down.', retryable: true } })
      try {
        const result = await core.tasks[checked.request.operation](guiPrincipal, checked.request.input)
        return reply(200, { ...result, requestId: checked.request.requestId })
      } catch (error) {
        log({ event: 'gui-task-request-failed', operation, error: String(error && error.message ? error.message : error) })
        return reply(200, { schemaVersion: 1, ok: false, requestId: checked.request.requestId, error: { code: 'INTERNAL', message: 'internal error', retryable: false } })
      }
    }
    webCtx.effect(() => webCtx.webServer.register({ kind: 'prefix', path: '/nexus/tasks/v1', handler }), 'nexus-controller: task API route')
  })

  // Turn ends of admitted managed turns; reconciliation-only owner mutations.
  ctx.on('session/event', (session, event) => {
    if (!session || !event || typeof event.type !== 'string' || !core.admission.isManaged(session)) return
    if (event.type === 'turn/end' && core.managedTasks && core.admission.rootOf(session) === session.id) {
      const reason = event.data && event.data.reason ? event.data.reason : null
      const error = reason && reason.error ? { code: reason.error.code ? String(reason.error.code) : null, message: String(reason.error.message || '').slice(0, 500) } : null
      core.managedTasks.onTurnEnd(session.id, reason ? reason.kind : null, error)
    }
    const kind = RECONCILED_EVENT_TYPES[event.type] || (event.type === 'turn/end' && event.data && event.data.reason && (event.data.reason.kind === 'aborted' || event.data.reason.kind === 'interrupted') ? 'cancel' : null)
    if (kind) core.admission.recordOwnerMutation(session, kind, { eventType: event.type, seq: event.seq })
  })
  log({ event: 'controller-started', build: CONTROLLER_BUILD, strategies: core.strategies.list().map((d) => d.id) })
}

module.exports = {
  name: 'nexus-controller',
  provide: CONTROLLER_SERVICE,
  apply,
  CONTROLLER_SERVICE,
  CONTROLLER_CONTRACT_MAJOR,
  CONTROLLER_BUILD,
  MANDATORY_STRATEGY_IDS,
  GATEWAY_HOOK_DIGESTS,
  verifyGatewayHook,
  ControllerError,
  createControllerCore,
  resolveControllerAccess,
  isCordisContext,
}
